package server

import (
	"testing"

	podpkg "github.com/sandrpod/sandrpod/pkg/sandpod"
)

// Fixed vectors generated by the published e2b SDK's get_signature:
// sha256("<path>:<operation>:<user>:<token>[:<expiration>]"), base64raw,
// prefixed "v1_".
func TestVerifyFileSignature(t *testing.T) {
	const (
		sandbox   = "sb-file-sig"
		token     = "e2b_abc"
		path      = "/tmp/a.txt"
		readSig   = "v1_5e4SXQwhZhLOgmthCiIPtbfp0j9bxRzPFzkKMtyBjKs"
		futureSig = "v1_7zO+sSJIxJ5Rur/qANcjjuvW4xkzgmIo+W3nceFOFAA"
		pastSig   = "v1_1rsPgScavOZc1/zJlCam8E/+LqNx5aDabvTixbuu33g"
		futureExp = int64(4102444800)
		pastExp   = int64(1000000000)
	)
	store := podpkg.NewSandboxStore()
	if err := store.Add(&podpkg.SandboxInfo{
		Name:        sandbox,
		DisplayName: "file-sig",
		Labels:      map[string]string{e2bEnvdTokenLabel: token},
	}); err != nil {
		t.Fatal(err)
	}
	d := e2bDeps{sandboxes: store}

	cases := []struct {
		name       string
		sandbox    string
		path       string
		operation  string
		user       string
		signature  string
		expiration int64
		want       bool
	}{
		{"read", sandbox, path, "read", "", readSig, 0, true},
		{"wrong operation", sandbox, path, "write", "", readSig, 0, false},
		{"wrong path", sandbox, "/tmp/other", "read", "", readSig, 0, false},
		{"wrong sandbox", "sb-other", path, "read", "", readSig, 0, false},
		{"future expiration", sandbox, path, "write", "", futureSig, futureExp, true},
		{"expiration missing", sandbox, path, "write", "", futureSig, 0, false},
		{"expired", sandbox, path, "write", "", pastSig, pastExp, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := d.verifyFileSignature(tc.sandbox, tc.path, tc.operation,
				tc.user, tc.signature, tc.expiration)
			if got != tc.want {
				t.Fatalf("verifyFileSignature() = %v, want %v", got, tc.want)
			}
		})
	}
}

func TestE2BSensitivePort(t *testing.T) {
	for _, p := range []int{5900, 6080, 6901, 9222, 9223} {
		if !e2bSensitivePort(p) {
			t.Errorf("port %d should require preview auth", p)
		}
	}
	for _, p := range []int{8000, 8080, 50005, 49983, 3000} {
		if e2bSensitivePort(p) {
			t.Errorf("port %d should be a public in-sandbox service", p)
		}
	}
}
